def test_runtime_has_no_hub_internal_imports():
        root = Path(__file__).parents[1]
        violations = []
        for path in (root / 'nginx_qa').glob('channel*.py'):
            for node in ast.walk(ast.parse(path.read_text())):
                if isinstance(node, ast.ImportFrom) and (node.module or '').startswith('agent_channel_bridge'):
                    violations.append(f'{path.name}:{node.lineno}')
                if isinstance(node, ast.Import):
                    violations.extend(f'{path.name}:{node.lineno}' for item in node.names if item.name.startswith('agent_channel_bridge'))
